export function validarLivro(dados) {
  const erros = [];

  if (typeof dados?.titulo !== 'string' || dados.titulo.trim() === '') {
    erros.push('titulo é obrigatório');
  }
  if (typeof dados?.autor !== 'string' || dados.autor.trim() === '') {
    erros.push('autor é obrigatório');
  }
  if (typeof dados?.preco !== 'number' || !Number.isFinite(dados.preco) || dados.preco < 0) {
    erros.push('preco deve ser um número maior ou igual a zero');
  }
  if (dados?.categoria !== undefined && (typeof dados.categoria !== 'string' || dados.categoria.trim() === '')) {
    erros.push('categoria deve ser um texto');
  }

  if (erros.length > 0) return { ok: false, erros };

  const livro = { titulo: dados.titulo.trim(), autor: dados.autor.trim(), preco: dados.preco };
  if (typeof dados.categoria === 'string' && dados.categoria.trim() !== '') {
    livro.categoria = dados.categoria.trim();
  }
  return { ok: true, livro };
}

