export function montarPagina(lista, pagina, itensPorPagina) {
  if (itensPorPagina <= 0) {
    itensPorPagina = 1; // tamanho de página inválido: usa o mínimo
  }
  const total = lista.length;

  // total de páginas: quantas fatias de itensPorPagina cobrem a lista
  let totalPaginas = 0;
  for (let i = 0; i < total; i = i + itensPorPagina) {
    totalPaginas += 1;
  }
  if (totalPaginas === 0) {
    totalPaginas = 1;
  }

  const inicio = (pagina - 1) * itensPorPagina;

  return {
    itens: lista.slice(inicio, inicio + itensPorPagina),
    total,
    pagina,
    itensPorPagina,
    totalPaginas,
    links: {
      anterior: pagina > 1 ? { pagina: pagina - 1 } : null,
      proxima: pagina < totalPaginas ? { pagina: pagina + 1 } : null,
    },
  };
}

export function formatarErro(status, codigo, mensagem) {
  return { status, corpo: { erro: { codigo, mensagem } } };
}

