import { validarLivro } from './validacao.mjs';
import { montarPagina, formatarErro } from './resposta.mjs';

export function atenderPedido(catalogo, pedido) {
  const metodo = pedido.metodo ?? 'GET';
  const caminho = pedido.caminho ?? '/';
  const query = pedido.query ?? {};

  if (metodo === 'GET' && caminho === '/livros') {
    const pagina = lerInteiro(query.pagina, 1);
    const itensPorPagina = lerInteiro(query.itens, 2);
    if (pagina === null || itensPorPagina === null) {
      return formatarErro(400, 'pagina_invalida', 'pagina e itens devem ser números inteiros maiores que zero');
    }
    return { status: 200, corpo: montarPagina(catalogo, pagina, itensPorPagina) };
  }

  if (metodo === 'GET' && caminho.startsWith('/livros/')) {
    const id = Number(caminho.slice('/livros/'.length));
    const livro = catalogo.find((l) => l.id === id);
    if (!livro) {
      return formatarErro(404, 'livro_nao_encontrado', 'livro ' + id + ' não encontrado');
    }
    return { status: 200, corpo: { livro, links: { self: '/livros/' + id } } };
  }

  if (metodo === 'POST' && caminho === '/livros') {
    const validacao = validarLivro(pedido.corpo);
    if (!validacao.ok) {
      return formatarErro(400, 'dados_invalidos', validacao.erros.join('; '));
    }
    const livro = { id: catalogo.length + 1, ...validacao.livro };
    return {
      status: 201,
      corpo: { livro, links: { self: '/livros/' + livro.id } },
      catalogo: [...catalogo, livro],
    };
  }

  return formatarErro(405, 'metodo_nao_permitido', 'método ' + metodo + ' não permitido para ' + caminho);
}

function lerInteiro(valor, padrao) {
  if (valor === undefined) return padrao;
  const numero = Number(valor);
  return Number.isInteger(numero) && numero >= 1 ? numero : null;
}

