import { test } from 'node:test';
import assert from 'node:assert/strict';
import { validarLivro } from './lib/validacao.mjs';
import { montarPagina, formatarErro } from './lib/resposta.mjs';
import { atenderPedido } from './lib/rota.mjs';

const livrosBase = [
  { id: 1, titulo: 'Dom Casmurro', autor: 'Machado de Assis', preco: 39.9 },
  { id: 2, titulo: 'O Cortiço', autor: 'Aluísio Azevedo', preco: 29.9 },
  { id: 3, titulo: 'Memórias Póstumas', autor: 'Machado de Assis', preco: 45 },
];

test('POST válido cadastra e devolve 201 com link (validação + rota)', () => {
  const resposta = atenderPedido([], {
    metodo: 'POST',
    caminho: '/livros',
    corpo: { titulo: '  Grande Sertão  ', autor: 'Guimarães Rosa', preco: 52.5 },
  });
  assert.equal(resposta.status, 201);
  assert.equal(resposta.corpo.livro.id, 1);
  assert.equal(resposta.corpo.livro.titulo, 'Grande Sertão'); // trim aplicado
  assert.deepEqual(resposta.corpo.links, { self: '/livros/1' });
  assert.equal(resposta.catalogo.length, 1);
  assert.equal(resposta.catalogo[0].titulo, 'Grande Sertão');
});

test('POST inválido devolve 400 formatado e não mexe no catálogo', () => {
  const original = [...livrosBase];
  const resposta = atenderPedido(livrosBase, {
    metodo: 'POST',
    caminho: '/livros',
    corpo: { titulo: '', preco: -1 },
  });
  assert.equal(resposta.status, 400);
  assert.equal(resposta.corpo.erro.codigo, 'dados_invalidos');
  assert.match(resposta.corpo.erro.mensagem, /titulo é obrigatório/);
  assert.deepEqual(livrosBase, original);
});

test('GET com paginação devolve página com links (resposta + rota)', () => {
  const resposta = atenderPedido(livrosBase, {
    metodo: 'GET',
    caminho: '/livros',
    query: { pagina: '2', itens: '2' },
  });
  assert.equal(resposta.status, 200);
  assert.deepEqual(resposta.corpo.itens, [{ id: 3, titulo: 'Memórias Póstumas', autor: 'Machado de Assis', preco: 45 }]);
  assert.equal(resposta.corpo.total, 3);
  assert.equal(resposta.corpo.totalPaginas, 2);
  assert.deepEqual(resposta.corpo.links.anterior, { pagina: 1 });
  assert.equal(resposta.corpo.links.proxima, null);
});

test('GET /livros/:id devolve o livro ou 404 formatado', () => {
  const achado = atenderPedido(livrosBase, { metodo: 'GET', caminho: '/livros/2' });
  assert.equal(achado.status, 200);
  assert.equal(achado.corpo.livro.titulo, 'O Cortiço');

  const faltando = atenderPedido(livrosBase, { metodo: 'GET', caminho: '/livros/99' });
  assert.equal(faltando.status, 404);
  assert.equal(faltando.corpo.erro.codigo, 'livro_nao_encontrado');
});

test('query de paginação inválida devolve 400 formatado', () => {
  const resposta = atenderPedido(livrosBase, { metodo: 'GET', caminho: '/livros', query: { pagina: 'x' } });
  assert.equal(resposta.status, 400);
  assert.equal(resposta.corpo.erro.codigo, 'pagina_invalida');
});

test('método não permitido devolve 405 formatado', () => {
  const resposta = atenderPedido(livrosBase, { metodo: 'DELETE', caminho: '/livros/1' });
  assert.equal(resposta.status, 405);
  assert.equal(resposta.corpo.erro.codigo, 'metodo_nao_permitido');
});
